/**
 * API 服务端词条库（i18n 基建）：消息层文案按站点语言（setting.lang）取词。
 *  - 源语言 zh-cn 必填且与既有测试断言逐字一致；
 *    其余 9 语言（zh-tw en-us ru-ru th-th de-de ja-jp ko-kr es-es fr-fr）全量提供。
 *  - createApiT(lang) 返回同步翻译器：lang 命中 → zh-cn 回落 → 键名兜底；{param} 插值。
 *  - 路由/中间件经全局中间件取词（c.get('t')）；核心纯函数以可选 t 参数注入（缺省 t0 = zh-cn，
 *    兼容单测直调）。插件 manifest/schema 多语言文案用 L() 位置式构造（前端 extText 取词）；
 *    插件运行时 reason 约定返回 API_MESSAGES 词条键，路由层 t() 翻译后返回用户。
 *  - 占位符用 {name}（如 {credit}/{site}/{code}/{link}/{n}/{old}/{new}/{todo}/{topic}/{forum}/{name}/{subject}）。
 */

import type { ApiKey } from '@freeidx/shared';

export const LOCALES = ['zh-cn', 'zh-tw', 'en-us', 'ru-ru', 'th-th', 'de-de', 'ja-jp', 'ko-kr', 'es-es', 'fr-fr'] as const;
type Locale = (typeof LOCALES)[number];

type MsgDict = { 'zh-cn': string } & Partial<Record<Locale, string>>;

/** 位置式构造：zh-cn, zh-tw, en-us, ru-ru, th-th, de-de, ja-jp, ko-kr, es-es, fr-fr */
const M = (a: string, b: string, c: string, d: string, e: string, f: string, g: string, h: string, i: string, j: string): MsgDict => ({
  'zh-cn': a, 'zh-tw': b, 'en-us': c, 'ru-ru': d, 'th-th': e, 'de-de': f, 'ja-jp': g, 'ko-kr': h, 'es-es': i, 'fr-fr': j,
});

type Loc = Record<string, string>;

/** 位置式构造插件多语言文案（manifest.name / schema LocText，10 语言）：参数顺序同 M */
export const L = (a: string, b: string, c: string, d: string, e: string, f: string, g: string, h: string, i: string, j: string): Loc => ({
  'zh-cn': a, 'zh-tw': b, 'en-us': c, 'ru-ru': d, 'th-th': e, 'de-de': f, 'ja-jp': g, 'ko-kr': h, 'es-es': i, 'fr-fr': j,
});

