export type ApiT = (key: ApiKey, params?: Record<string, string | number>) => string;

/** 缺省翻译器（zh-cn）：核心纯函数可选参数与 handleError 兜底用 */
export const t0: ApiT = (key, params) => translate(key, 'zh-cn', params);

function translate(key: ApiKey, lang: string, params?: Record<string, string | number>): string {
  const entry = API_MESSAGES[key];
  let s = entry ? entry[lang as Locale] || entry['zh-cn'] : key;
  if (params) {
    for (const [k, v] of Object.entries(params)) s = s.split(`{${k}}`).join(String(v));
  }
  return s;
}

/** 按站点语言构造同步翻译器：lang 命中 → zh-cn 回落 → 键名兜底；{param} 插值 */
export function createApiT(lang: string): ApiT {
  const l = String(lang || 'en-us').toLowerCase();
  return (key, params) => translate(key, l, params);
}
